-- Stagedoor dataset for SELECT * FROM production.
-- Run this once in a Databricks SQL editor or notebook. It creates the 15 practice tables
-- in the schema of your choice (default: main.stagedoor) and loads every row.
-- Generated by tools/export-databricks.js; do not edit by hand.

CREATE SCHEMA IF NOT EXISTS stagedoor;
USE SCHEMA stagedoor;

-- customers: One row per customer. referred_by points at another customer.
CREATE OR REPLACE TABLE customers (
  customer_id INT,
  full_name STRING,
  email STRING,
  city STRING,
  country STRING,
  signup_date DATE,
  loyalty_tier STRING,
  referred_by INT,
  marketing_opt_in BOOLEAN
) COMMENT 'One row per customer. referred_by points at another customer.';

-- venues: One row per venue.
CREATE OR REPLACE TABLE venues (
  venue_id INT,
  name STRING,
  city STRING,
  country STRING,
  capacity INT
) COMMENT 'One row per venue.';

-- events: One row per concert.
CREATE OR REPLACE TABLE events (
  event_id INT,
  artist STRING,
  event_name STRING,
  venue_id INT,
  event_date DATE,
  genre STRING,
  base_price DOUBLE
) COMMENT 'One row per concert.';

-- orders: One row per order. status is PLACED, PAID, CANCELLED or REFUNDED.
CREATE OR REPLACE TABLE orders (
  order_id INT,
  customer_id INT,
  event_id INT,
  order_ts TIMESTAMP,
  status STRING,
  channel STRING,
  promo_code STRING
) COMMENT 'One row per order. status is PLACED, PAID, CANCELLED or REFUNDED.';

-- order_items: One row per order line.
CREATE OR REPLACE TABLE order_items (
  order_id INT,
  line_no INT,
  ticket_type STRING,
  quantity INT,
  unit_price DOUBLE
) COMMENT 'One row per order line.';

-- payments: One row per payment attempt. Some orders were charged twice.
CREATE OR REPLACE TABLE payments (
  payment_id INT,
  order_id INT,
  paid_ts TIMESTAMP,
  amount DOUBLE,
  method STRING,
  status STRING
) COMMENT 'One row per payment attempt. Some orders were charged twice.';

-- refunds: One row per refund. One refund points at an order that does not exist.
CREATE OR REPLACE TABLE refunds (
  refund_id INT,
  order_id INT,
  refund_ts TIMESTAMP,
  amount DOUBLE,
  reason STRING
) COMMENT 'One row per refund. One refund points at an order that does not exist.';

-- page_views: Clickstream. customer_id is NULL for anonymous visitors.
CREATE OR REPLACE TABLE page_views (
  view_id INT,
  customer_id INT,
  viewed_ts TIMESTAMP,
  page STRING,
  event_id INT,
  device STRING
) COMMENT 'Clickstream. customer_id is NULL for anonymous visitors.';

-- employees: Org chart. manager_id points at another employee.
CREATE OR REPLACE TABLE employees (
  employee_id INT,
  name STRING,
  title STRING,
  manager_id INT,
  department STRING,
  hire_date DATE,
  salary INT
) COMMENT 'Org chart. manager_id points at another employee.';

-- support_tickets: One row per ticket. closed_ts is NULL while open.
CREATE OR REPLACE TABLE support_tickets (
  ticket_id INT,
  customer_id INT,
  opened_ts TIMESTAMP,
  closed_ts TIMESTAMP,
  priority STRING,
  status STRING,
  agent_id INT
) COMMENT 'One row per ticket. closed_ts is NULL while open.';

-- seat_inventory: Daily snapshot of unsold seats. Some days are missing.
CREATE OR REPLACE TABLE seat_inventory (
  event_id INT,
  snapshot_date DATE,
  seats_remaining INT
) COMMENT 'Daily snapshot of unsold seats. Some days are missing.';

-- raw_signups: Raw, unvalidated sign-up form data.
CREATE OR REPLACE TABLE raw_signups (
  signup_id INT,
  email STRING,
  full_name STRING,
  signup_date STRING,
  country STRING,
  phone STRING
) COMMENT 'Raw, unvalidated sign-up form data.';

-- app_events: Mobile app events as JSON strings.
CREATE OR REPLACE TABLE app_events (
  event_seq INT,
  event_ts TIMESTAMP,
  payload STRING
) COMMENT 'Mobile app events as JSON strings.';

-- carts: Shopping carts. items is an array of structs.
CREATE OR REPLACE TABLE carts (
  cart_id INT,
  customer_id INT,
  updated_ts TIMESTAMP,
  items ARRAY<STRUCT<event_id: INT, ticket_type: STRING, qty: INT, unit_price: DOUBLE>>,
  ticket_types ARRAY<STRING>
) COMMENT 'Shopping carts. items is an array of structs.';

-- fx_rates: Exchange rates to USD, each valid for a date range.
CREATE OR REPLACE TABLE fx_rates (
  currency STRING,
  valid_from DATE,
  valid_to DATE,
  usd_rate DOUBLE
) COMMENT 'Exchange rates to USD, each valid for a date range.';

SELECT 'Loaded 15 tables' AS status;
